mapper.select:
select TDY_ACCUMUL_PAY_FEE from PTL_FEE_POSITION
where PORTFOLIO_ID = #{ptlId}
  and 1 = to_date(#{cdate}, 'yyyy-MM-dd') - CDATE
  and PTL_FEE_TYPE = #{feeType}

SELECT SUM(NVL(TDY_UNPAID_INTINCEXP, 0)) FROM (
	select TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE
	where FEE_TYPE = #{feeType}
	  and 1 = to_date(#{cdate}, 'yyyy-MM-dd') - CDATE
	  and FINPROD_ID = #{finprodId}
	  and P_FINPROD_ID IS NULL
	UNION ALL
	select TDY_UNPAID_INTINCEXP from BOK_POSITION_PRDFEE
	where FEE_TYPE = #{feeType}
	  and 1 = to_date(#{cdate}, 'yyyy-MM-dd') - CDATE
	  and FINPROD_ID = #{finprodId}
	  and P_FINPROD_ID IS not NULL
	)

select FINPROD_ID finprodId,FEE_TYPE feeType,BRANCH branch,'' sFinprodId, CDATE cdate, TDY_POSITION tdyPosition, TDY_FEE_RATE tdyFeeRate, TDY_INTINCEXP_ADD tdyIntincexpAdd from BOK_POSITION_PRDFEE where FEE_TYPE = #{feeType} and CDATE >= to_date(#{startDate}, 'yyyy-MM-dd') and CDATE < to_date(#{enddate}, 'yyyy-MM-dd') and FINPROD_ID = #{finprodId}
and BRANCH = #{branch}
and P_FINPROD_ID IS NULL UNION ALL select FINPROD_ID finprodId,FEE_TYPE feeType,BRANCH branch,'' sFinprodId, CDATE cdate, TDY_POSITION tdyPosition, TDY_FEE_RATE tdyFeeRate, TDY_INTINCEXP_ADD tdyIntincexpAdd from BOK_POSITION_PRDFEE where FEE_TYPE = #{feeType} and CDATE >= to_date(#{startDate}, 'yyyy-MM-dd') and CDATE < to_date(#{enddate}, 'yyyy-MM-dd') and P_FINPROD_ID = #{finprodId}
and BRANCH = #{branch}
UNION ALL select B.FINPROD_ID finprodId ,ptl_FEE_TYPE feeType, 0 branch ,'' sFinprodId , CDATE cdate , NVL(TDY_FEE_CAPITAL,0) tdyPosition , NVL(TDY_FEE_RATE,0) tdyFeeRate, TDY_ACCUMUL_PAY_FEE tdyIntincexpAdd from PTL_FEE_POSITION A inner join FIN_PRODUCT_ADD B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID INNER JOIN FIN_PRODUCT C ON B.FINPROD_ID=C.FINPROD_ID where A.ptl_FEE_TYPE = #{feeType} AND C.PROFIT_TYPE = #{profitType} AND C.P_FINPROD_ID IS NULL and A.CDATE >= to_date(#{startDate}, 'yyyy-MM-dd') and A.CDATE < to_date(#{enddate}, 'yyyy-MM-dd') and B.FINPROD_ID = #{finprodId} UNION ALL SELECT decode(BOK_POSITION_PRDFEE.FINPROD_ID,FIN_PRODUCT.FINPROD_MARKET_ID,FIN_PRODUCT1.FINPROD_MARKET_ID,BOK_POSITION_PRDFEE.FINPROD_ID) finprodId, BOK_POSITION_PRDFEE.Fee_Type feeType, 0 AS branch , decode(BOK_POSITION_PRDFEE.P_FINPROD_ID,NULL,FIN_PRODUCT1.FINPROD_MARKET_ID,BOK_POSITION_PRDFEE.Finprod_Id) sFinprodId, BOK_POSITION_PRDFEE.CDATE cdate, BOK_POSITION_PRDFEE.TDY_POSITION AS tdyPosition, BOK_POSITION_PRDFEE.TDY_FEE_RATE AS tdyFeeRate , nvl(BOK_POSITION_PRDFEE.TDY_INTINCEXP_ADD,0) AS tdyIntincexpAdd FROM BOK_POSITION_PRDFEE LEFT JOIN FIN_PRODUCT ON BOK_POSITION_PRDFEE.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT FIN_PRODUCT1 ON BOK_POSITION_PRDFEE.P_FINPROD_ID = FIN_PRODUCT1.FINPROD_ID where BOK_POSITION_PRDFEE.FINPROD_ID = #{finprodId}
AND BOK_POSITION_PRDFEE.FEE_TYPE = #{feeType} AND BOK_POSITION_PRDFEE.P_FINPROD_ID IS NOT NULL and BOK_POSITION_PRDFEE.CDATE >= to_date(#{startDate}, 'yyyy-MM-dd') and BOK_POSITION_PRDFEE.CDATE < to_date(#{enddate}, 'yyyy-MM-dd')

select FIN_PRODUCT_ADD.FINPROD_ID finprodId, BOK_POSITION_PRDFEE.BRANCH branch, '' sFinprodId, SUM(NVL(BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP, 0)) actPayAmt from BOK_POSITION_PRDFEE, FIN_PRODUCT_ADD, FIN_PRODUCT where BOK_POSITION_PRDFEE.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}
and BOK_POSITION_PRDFEE.FEE_TYPE = #{feeType}
and BOK_POSITION_PRDFEE.CDATE = to_date(#{calcEndDate}, 'yyyy-MM-dd')
and 1 = to_date(#{calcEndDate}, 'yyyy-MM-dd') -BOK_POSITION_PRDFEE.CDATE
and BOK_POSITION_PRDFEE.P_FINPROD_ID is NULL group by FIN_PRODUCT_ADD.FINPROD_ID, BOK_POSITION_PRDFEE.BRANCH union all
select FIN_PRODUCT_ADD.FINPROD_ID finprodId, BOK_POSITION_PRDFEE.BRANCH branch, BOK_POSITION_PRDFEE.FINPROD_ID sFinprodId, SUM(NVL(BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP, 0)) actPayAmt from BOK_POSITION_PRDFEE, FIN_PRODUCT_ADD, FIN_PRODUCT,FIN_PRODUCT F1 where BOK_POSITION_PRDFEE.P_FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND F1.P_FINPROD_ID=FIN_PRODUCT_ADD.FINPROD_ID
and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}
and BOK_POSITION_PRDFEE.FEE_TYPE = #{feeType}
and BOK_POSITION_PRDFEE.CDATE = to_date(#{calcEndDate}, 'yyyy-MM-dd')
and 1 = to_date(#{calcEndDate}, 'yyyy-MM-dd') -BOK_POSITION_PRDFEE.CDATE
group by FIN_PRODUCT_ADD.FINPROD_ID, BOK_POSITION_PRDFEE.BRANCH,BOK_POSITION_PRDFEE.FINPROD_ID union all
select FIN_PRODUCT_ADD.FINPROD_ID finprodId, 0 branch, '' sFinprodId, SUM(NVL(PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE, 0)) actPayAmt from PTL_FEE_POSITION, FIN_PRODUCT_ADD, FIN_PRODUCT where PTL_FEE_POSITION.PORTFOLIO_ID = FIN_PRODUCT_ADD.PORTFOLIO_ID and FIN_PRODUCT_ADD.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}
and PTL_FEE_POSITION.PTL_FEE_TYPE = #{feeType} and 1 = to_date(#{calcEndDate}, 'yyyy-MM-dd') - PTL_FEE_POSITION.CDATE and FIN_PRODUCT.p_Finprod_Id is null group by FIN_PRODUCT_ADD.FINPROD_ID

SELECT TEMP.finprodMarketId finprodMarketId, TEMP.finprodId finprodId, TEMP.sFinprodId sFinprodId, TEMP.feeId feeId, sys_datadict_list.item_value basicBill, TEMP.feeName feeName, TEMP.feeType feeType, TEMP.calcStartDate calcStartDate, TEMP.calcEndDate calcEndDate, TEMP.ccy ccy, TEMP.actPayAmt actPayAmt, TEMP.payAmt payAmt FROM( SELECT FIN_PRODUCT_ADD.PORTFOLIO_ID finprodMarketId ,FIN_PRODUCT.Finprod_Id finprodId ,NULL as sFinprodId ,MST_FEEINFO.FEE_ID feeId ,MST_FEEINFO.BASIC_BILL basicBill ,MST_FEEINFO.Fee_Name feeName ,BOK_POSITION_PRDFEE.FEE_TYPE feeType ,TRD_PRODUCT_DEAL.MDATE as calcStartDate ,to_date(#{calcEndDate}, 'yyyy-MM-dd') calcEndDate ,FIN_CASH_INFO.ccy ,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as actPayAmt ,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as payAmt FROM FIN_CASH_INFO INNER JOIN FIN_CASH_PAY_RULE ON FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID
AND FIN_CASH_PAY_RULE.PAY_CYCLE != #{payCycle}
AND FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle}
INNER JOIN MST_FEEINFO ON FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID AND MST_FEEINFO.CHARGE_TYPE IN(#{chargeType}) INNER JOIN BOK_POSITION_PRDFEE ON FIN_CASH_INFO.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND FIN_CASH_INFO.BRANCH = BOK_POSITION_PRDFEE.BRANCH and FIN_CASH_INFO.CASH_TYPE_2 = BOK_POSITION_PRDFEE.FEE_TYPE LEFT JOIN ( SELECT MDATE,FINPROD_ID,BRANCH,FINPROD_TYPE2 FROM TRD_PRODUCT_DEAL S WHERE S.PS = #{ps} AND S.IS_CANCEL = #{isCancel} AND MDATE = (select MAX(d.MDATE) from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') AND d.IS_CANCEL = #{isCancel} AND S.FINPROD_ID=D.FINPROD_ID AND S.BRANCH=D.BRANCH AND S.FINPROD_TYPE2=D.FINPROD_TYPE2 ))TRD_PRODUCT_DEAL on FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FIN_CASH_INFO.BRANCH = TRD_PRODUCT_DEAL.BRANCH AND TRD_PRODUCT_DEAL.FINPROD_TYPE2 = BOK_POSITION_PRDFEE.FEE_TYPE LEFT JOIN FIN_PRODUCT ON FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID WHERE FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} AND FIN_PRODUCT.P_FINPROD_ID is null AND FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId} AND FIN_PRODUCT.FINPROD_ID = #{finprodId} AND MST_FEEINFO.FEE_ID = #{feeId} AND BOK_POSITION_PRDFEE.CDATE = (SELECT max(B.CDATE) FROM BOK_POSITION_PRDFEE B WHERE B.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND B.BRANCH = BOK_POSITION_PRDFEE.BRANCH AND BOK_POSITION_PRDFEE.FEE_TYPE = B.FEE_TYPE AND B.CDATE <to_date(#{calcEndDate}, 'yyyy-MM-dd')) UNION SELECT FIN_PRODUCT_ADD.PORTFOLIO_ID finprodMarketId ,FIN_PRODUCT1.FINPROD_MARKET_ID finprodId ,FIN_PRODUCT.FINPROD_ID as sFinprodId ,MST_FEEINFO.FEE_ID feeId ,MST_FEEINFO.BASIC_BILL basicBill ,MST_FEEINFO.Fee_Name feeName ,BOK_POSITION_PRDFEE.FEE_TYPE feeType ,TRD_PRODUCT_DEAL.MDATE as calcStartDate ,to_date(#{calcEndDate}, 'yyyy-MM-dd') calcEndDate ,FIN_CASH_INFO.ccy ,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as actPayAmt ,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as payAmt FROM FIN_CASH_INFO INNER JOIN FIN_CASH_PAY_RULE ON FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID
AND FIN_CASH_PAY_RULE.PAY_CYCLE != #{payCycle}
AND FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle}
INNER JOIN MST_FEEINFO ON FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID AND MST_FEEINFO.CHARGE_TYPE IN(#{chargeType}) INNER JOIN BOK_POSITION_PRDFEE ON FIN_CASH_INFO.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND FIN_CASH_INFO.BRANCH = BOK_POSITION_PRDFEE.BRANCH and FIN_CASH_INFO.CASH_TYPE_2 = BOK_POSITION_PRDFEE.FEE_TYPE LEFT JOIN ( SELECT MDATE,FINPROD_ID,BRANCH,FINPROD_TYPE2 FROM TRD_PRODUCT_DEAL S WHERE S.PS = #{ps} AND S.IS_CANCEL = #{isCancel} AND MDATE = (select MAX(d.MDATE) from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') AND d.IS_CANCEL = #{isCancel} AND S.FINPROD_ID=D.FINPROD_ID AND S.BRANCH=D.BRANCH AND S.FINPROD_TYPE2=D.FINPROD_TYPE2 ))TRD_PRODUCT_DEAL on FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FIN_CASH_INFO.BRANCH = TRD_PRODUCT_DEAL.BRANCH AND TRD_PRODUCT_DEAL.FINPROD_TYPE2 = BOK_POSITION_PRDFEE.FEE_TYPE LEFT JOIN FIN_PRODUCT ON FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT FIN_PRODUCT1 ON BOK_POSITION_PRDFEE.FINPROD_ID = FIN_PRODUCT1.FINPROD_ID
LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT1.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID WHERE FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} AND FIN_PRODUCT.P_FINPROD_ID is not null AND FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId} AND FIN_PRODUCT.P_FINPROD_ID = #{finprodId} AND MST_FEEINFO.FEE_ID = #{feeId} AND BOK_POSITION_PRDFEE.CDATE = (SELECT max(B.CDATE) FROM BOK_POSITION_PRDFEE B WHERE B.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND B.BRANCH = BOK_POSITION_PRDFEE.BRANCH AND BOK_POSITION_PRDFEE.FEE_TYPE = B.FEE_TYPE
AND B.CDATE <to_date(#{calcEndDate}, 'yyyy-MM-dd'))
union all
select PTL_PORTFOLIO.PORTFOLIO_ID finprodMarketId ,FIN_PRODUCT_ADD.FINPROD_ID finprodId ,'' as sFinprodId ,MST_FEEINFO.FEE_ID feeId ,MST_FEEINFO.BASIC_BILL basicBill ,MST_FEEINFO.Fee_Name feeName ,PTL_FEE_POSITION.PTL_FEE_TYPE feeType ,nvl(TRD_PRODUCT_DEAL.MDATE,PTL_PORTFOLIO.vdate) as calcStartDate ,to_date(#{calcEndDate}, 'yyyy-MM-dd') calcEndDate ,FIN_CASH_INFO.ccy ,PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE as actPayAmt ,PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE as payAmt from PTL_FEE_POSITION, FIN_PRODUCT_ADD, PTL_PORTFOLIO ,MST_FEEINFO, FIN_CASH_INFO LEFT JOIN ( SELECT MDATE,FINPROD_ID,BRANCH,FINPROD_TYPE2 FROM TRD_PRODUCT_DEAL S WHERE S.PS = #{ps} AND S.IS_CANCEL = #{isCancel} AND MDATE = (select MAX(d.MDATE) from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') AND d.IS_CANCEL = #{isCancel} AND S.FINPROD_ID=D.FINPROD_ID AND S.BRANCH=D.BRANCH AND S.FINPROD_TYPE2=D.FINPROD_TYPE2 ))TRD_PRODUCT_DEAL on FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FIN_CASH_INFO.BRANCH = TRD_PRODUCT_DEAL.BRANCH and FIN_CASH_INFO.CASH_TYPE_2 = TRD_PRODUCT_DEAL.FINPROD_TYPE2 where PTL_FEE_POSITION.PORTFOLIO_ID = FIN_PRODUCT_ADD.PORTFOLIO_ID and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2_C04} and FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID and PTL_FEE_POSITION.PTL_FEE_TYPE = FIN_CASH_INFO.CASH_TYPE_2 AND MST_FEEINFO.CHARGE_TYPE = #{chargeType} and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId} and PTL_FEE_POSITION.PTL_FEE_TYPE = #{feeType} and 1 = to_date(#{calcEndDate}, 'yyyy-MM-dd') - PTL_FEE_POSITION.CDATE and PTL_PORTFOLIO.PROFIT_TYPE = #{profitType} )TEMP left join sys_datadict_list on TEMP.basicBill = sys_datadict_list.item_code and dict_code = 'BILL_BASE_FEE_KIND'

    	select t.* from (select row_number() over() as rownum,FIN_PRODUCT.CCY as ccy ,
			   FIN_PRODUCT.FINPROD_ID as finprodId,
    		   FIN_PRODUCT.PROFIT_TYPE as profitType,
			   FIN_PRODUCT_ADD.DEAL_MODE  as dealMode,
    		   FIN_PRODUCT.MDATE,   mdate
    	  from FIN_PRODUCT, FIN_PRODUCT_ADD
			/*,  PA_FIN_PRODUCT*/
    	 where FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
    	   /*AND FIN_PRODUCT.FINPROD_ID = PA_FIN_PRODUCT.FINPROD_ID*/

		  	and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}

		  ) t where t.rownum = 1

   		SELECT NVL(TDY_ACCUMUL_PAY_FEE,0)
   		FROM PTL_FEE_POSITION
   		WHERE PTL_FEE_TYPE = #{feeType1}
			AND 1 = to_date(#{cdate}, 'yyyy-MM-dd')-CDATE
			AND PORTFOLIO_ID = #{ptlId}

				AND PTL_FEE_PLACE = #{org}
